`,i.jsxs(a.h3,{id:"lets-do-it-better",children:[i.jsx(a.a,{"aria-hidden":"true",tabIndex:"-1",href:"#lets-do-it-better",children:i.jsx(a.span,{className:"icon icon-link"})}),"Let's do it better"]}),`
`,i.jsx(a.p,{children:"So how can this experience be better? The ideal service would allow a user to see ratings from friends, family, as well as enthusiasts of interest to a user (similar to Twitter). These ratings need to present themselves in an intelligent context and should not require you to quit your current workflow to open a standalone app. This app needs to integrate with your conversations in real time. So how can we do this and who can pull off such a feat?"}),`
`,i.jsx(a.p,{children:"Apple (and possibly Facebook) are the companies most poised to launch a compelling review system described above. Apple, however, has a bigger incentive and bigger advantage in implementing such a concept using iMessages. IMessages is baked into the operating system and is available out of the box. Any new feature added to iMessages would reach millions of people overnight and instant adoption. iMessages knows the people that are important to you and understands the context / conversation in which it resides."}),`
`,i.jsxs(a.h3,{id:"solution",children:[i.jsx(a.a,{"aria-hidden":"true",tabIndex:"-1",href:"#solution",children:i.jsx(a.span,{className:"icon icon-link"})}),"Solution"]}),`
`,i.jsx(a.p,{children:"The mockups below show a really primitive rendition of the conceived rating system. The user interface and experience are quite simple. When a message is received containing a Point of interest (POI), your iPhone recognizes it is and allows you to click on it, thus opening up Apple Maps (similar to clicking on an address in iMessages). Additionally, when a POI is suggested, one of three additional things can happen:"}),`
`,i.jsxs(a.ol,{children:[`
`,i.jsx(a.li,{children:"POI is not previously rated by you or contacts: iMessages prompts you to rate the location. [left]"}),`
`,i.jsx(a.li,{children:"POI is not previously rated by you but rated by contacts: iMessages subtly shades the average rating given by your contacts and allows you to rate the location. [middle]"}),`
`,i.jsx(a.li,{children:"POI is previously rated by you: iMessages reminds you how you rated the location. [right]"}),`
`]}),`
`,i.jsxs(a.h3,{id:"smart",children:[i.jsx(a.a,{"aria-hidden":"true",tabIndex:"-1",href:"#smart",children:i.jsx(a.span,{className:"icon icon-link"})}),"Smart"]}),`
`,i.jsx(a.p,{children:"iMessages can also provide further insight while communicating with a single person or group. Ratings would be shared within the given context and could alert you when making a bad or good recommendation."}),`
`,i.jsxs(a.h3,{id:"other-exciting-implications",children:[i.jsx(a.a,{"aria-hidden":"true",tabIndex:"-1",href:"#other-exciting-implications",children:i.jsx(a.span,{className:"icon icon-link"})}),"Other exciting implications"]}),`
`,i.jsx(a.p,{children:"The ability to recommend POI’s by comparing the location of all parties involved and their respective ratings is even more exciting. Imagine a button you could press while in an iMessage chat that would link you to a list of POI’s highly rated by both parties. Along with that, you could also have a map that displays all POIs rated positively between those among the chat thread."}),`
`,i.jsx(a.p,{children:"While Facebook could implement a similar type of rating system, Facebook’s rating system of Likes is an absolute one that cannot differentiate between something that is liked and something that is liked a lot, this hindering the value proposition and usefulness especially in large groups."}),`
`,i.jsxs(a.h3,{id:"conclusion",children:[i.jsx(a.a,{"aria-hidden":"true",tabIndex:"-1",href:"#conclusion",children:i.jsx(a.span,{className:"icon icon-link"})}),"Conclusion"]}),`
`,i.jsx(a.p,{children:"Implementing such a feature would be a game changer for iMessage users while also serving as a strategic advantage for Apple. Rating data is essential for pushing the next generation of hardware / software and Apple has none. Devices can only get smarter if they know what you like and these ratings are one way to achieve that while not relying on third party services. Just as Apple did with Apple Maps, Apple needs to begin acquiring it’s own set of ratings and this is the best way to quickly get users on board and catch up to Yelp reviews and Google ratings."})]})}function H0(s={}){const{wrapper:a}={...ce(),...s.components};return a?i.jsx(a,{...s,children:i.jsx(tp,{...s})}):tp(s)}const tu=Object.freeze(Object.defineProperty({__proto__:null,default:H0,frontmatter:q0},Symbol.toStringTag,{value:"Module"})),X0={path:"/blog/how-to-create-adaptive-pie-charts-with-transitions-in-d3",date:"1414134000000",published:!0,tags:["D3.js","JavaScript"],title:"How to create adaptive pie donut charts with transitions in D3.js (interactive tutorial and example)"};function np(s){const a={a:"a",code:"code",h3:"h3",p:"p",pre:"pre",span:"span",...ce(),...s.components};return i.jsxs(i.Fragment,{children:[i.jsxs(a.p,{children:["Following up with my last blog post about adaptive line chart graphs (",i.jsx(a.a,{href:"/blog/how-to-create-live-updating-and-flexible-d3-line-charts-using-pseudo-data/",children:"link"}),"), I decided to apply this same concept of adaptive charts to a pie / donut chart. The goal is to create a chart similar to the one below, which updates to any new data thrown at it."]}),`
